import {RacingGarage,RaceSimulation,CARS,DIFFICULTIES,UPGRADE_COSTS,carById} from './racing-model.js';
import {drawRaceCar,drawRaceScene} from './racing-art.js';

class EngineSound {
 unlock(){try{if(!this.context){const Audio=globalThis.AudioContext||globalThis.webkitAudioContext;if(!Audio)return;const c=this.context=new Audio();this.gain=c.createGain();this.gain.gain.value=0;this.osc=c.createOscillator();this.osc.type='sawtooth';const filter=c.createBiquadFilter();filter.type='lowpass';filter.frequency.value=400;this.osc.connect(filter);filter.connect(this.gain);this.gain.connect(c.destination);this.osc.start();}this.context.resume()?.catch(()=>{});}catch{}}
 update(active,ratio,settings={}){const c=this.context;if(!c||c.state!=='running')return;const volume=active&&settings.sound&&settings.effects?(settings.volume??.55)*(settings.effectsVolume??.8)*.025:0;this.gain.gain.setTargetAtTime(volume,c.currentTime,.06);this.osc.frequency.setTargetAtTime(55+Math.min(1.4,ratio)*115,c.currentTime,.08);}
 mute(){if(this.gain&&this.context)this.gain.gain.setTargetAtTime(0,this.context.currentTime,.015);}
}

export function mountRacing(root,api){
 root.innerHTML=`<div class="race-heading"><div><p>SPEED GARDEN · TOP DOWN RACING</p><h1>스피드 정원 <span>🏎️</span></h1></div><div class="race-wallet"><span id="race-stage">STAGE 1</span><strong id="race-coins">🪙 500</strong><button id="race-sound" type="button" aria-label="소리 켜기 또는 끄기">🔊</button></div></div>
 <div id="race-garage"><section class="race-tuning"><div class="race-section-heading"><h2>🔧 선택 차량 튜닝</h2><span id="race-selected"></span><strong id="race-spec"></strong></div><p>엔진 · 핸들링 · 니트로를 Lv.5까지 강화하세요.</p><div id="race-upgrades" class="race-upgrades"></div></section>
 <section><div class="race-section-heading"><h2>차고 & 전시장 <small>18종</small></h2><nav id="race-categories" aria-label="차량 종류"><button data-category="all" type="button">전체 18</button><button data-category="luxury" type="button">프리미엄 11</button><button data-category="supercar" type="button">슈퍼카 7</button></nav></div><div id="race-car-grid" class="race-car-grid"></div></section>
 <section class="race-difficulty-section"><h2>🚦 레이스 난이도 <small>AI 라이벌 6대와 경쟁</small></h2><div id="race-difficulties" class="race-difficulties"></div></section>
 <div class="race-launch"><p>↑ W 가속 · ↓ S 브레이크 · ← → 조향 · Space 니트로<br>휴대폰에서는 화면의 페달을 누르세요.</p><div><button id="race-fresh" type="button" class="race-secondary" hidden>새 레이스</button><button id="race-start" type="button" class="race-primary">🏁 레이스 출발</button></div></div><p class="race-save-note" id="race-save-note" role="status">차량 · 동전 · 레이스 자동 저장</p></div>
 <section id="race-play" class="race-play" hidden aria-label="스피드 정원 레이스"><canvas id="race-canvas" width="1200" height="1440" tabindex="0" aria-label="탑뷰 레이싱. 방향키 또는 WASD로 주행, 스페이스로 니트로."></canvas>
 <div class="race-hud"><div class="race-hud-top"><div><small id="race-hud-stage">STAGE 1</small><strong><b id="race-speed">0</b> <small>km/h</small></strong><span id="race-hud-diff"></span></div><div><strong id="race-collected">🪙 +0</strong><button type="button" id="race-pause" aria-label="레이스 일시정지">Ⅱ</button><button type="button" id="race-home">차고로</button></div></div><div class="race-progress"><div><span>START</span><strong id="race-position">7위 / 7대</strong><span>FINISH 🏁</span></div><div class="race-progress-track" id="race-track"><i id="race-progress-fill"></i><b id="race-player-marker">🏎️</b></div></div><p id="race-event" class="race-event" hidden role="status"></p></div>
 <div id="race-countdown" class="race-countdown" aria-live="polite"></div>
 <div class="race-controls"><div class="race-nitro"><span>⚡ NITRO</span><progress id="race-nitro" max="100" value="55" aria-label="남은 니트로"></progress><b id="race-nitro-value">55%</b></div><div class="race-pedals"><div><button type="button" data-drive="left" aria-label="왼쪽 조향">◀</button><button type="button" data-drive="right" aria-label="오른쪽 조향">▶</button></div><div><button type="button" data-drive="nitro" class="race-nitro-pedal">🔥<small>NITRO</small></button><button type="button" data-drive="brake">🛑<small>브레이크</small></button><button type="button" data-drive="accel" class="race-accel">⚡<small>가속</small></button></div></div></div>
 <div id="race-paused" class="race-paused" hidden><strong>잠깐, 피트 스톱</strong><p>준비되면 다시 출발해요.</p><button type="button" id="race-resume" class="race-primary">이어서 달리기 →</button></div>
 <div id="race-result" class="race-result" hidden><div><div id="race-result-icon">🏆</div><h2 id="race-result-title"></h2><p id="race-result-stage"></p><dl id="race-result-details"></dl><p id="race-result-status" role="status"></p><div><button type="button" id="race-result-garage" class="race-secondary">차고 · 업그레이드</button><button type="button" id="race-result-next" class="race-primary">다음 스테이지 →</button></div></div></div></section>`;
 const $=id=>root.querySelector('#'+id),canvas=$('race-canvas'),ctx=canvas.getContext('2d');ctx.setTransform(2,0,0,2,0,0);
 const engine=new EngineSound(),heldKeys=new Set(),touches=new Map();let garage=null,race=null,last=0,autosave=0,manualPause=false,settled=null,hasResult=false;
 const active=()=>api.current()==='racing',blocked=()=>!active()||document.hidden||!!document.querySelector('dialog[open]');
 const safe=fn=>{try{return fn();}catch(error){api.toast(error.message||'레이스를 준비하지 못했어요.');return null;}};
 const resetInputs=()=>{physicalKeys.clear();heldKeys.clear();touches.clear();for(const b of root.querySelectorAll('[data-drive]'))b.classList.remove('pressed');engine.mute();};
 const drive=()=>Object.fromEntries(['left','right','accel','brake','nitro'].map(k=>[k,heldKeys.has(k)||[...touches.values()].includes(k)]));
 const money=n=>n.toLocaleString('ko-KR');
 function save(){if(!garage)return;try{if(race&&['countdown','racing'].includes(race.phase))garage.checkpoint(race);else garage.save();$('race-save-note').textContent='차량 · 동전 · 레이스 자동 저장';}catch(error){$('race-save-note').textContent='저장 공간을 확인해 주세요. 현재 화면에서 다시 시도할 수 있어요.';throw error;}}
 function updateWallet(){$('race-coins').textContent='🪙 '+money(garage.data.coins);$('race-stage').textContent='STAGE '+garage.data.stage;$('race-sound').textContent=api.settings?.().sound?'🔊':'🔇';}
 function renderGarage(){
  const p=garage.data,car=garage.car,u=p.upgrades[car.id];updateWallet();$('race-selected').textContent=car.name;$('race-spec').textContent=`최고속도 ${car.maxSpeed} km/h`;$('race-upgrades').replaceChildren();
  for(const [key,label,icon]of [['speed','엔진','🚀'],['handling','서스펜션','🛞'],['nitro','니트로','⚡']]){const card=document.createElement('div'),b=document.createElement('button');card.innerHTML=`<div><strong>${icon} ${label}</strong><span>Lv.${u[key]} / 5</span></div><progress max="5" value="${u[key]}" aria-label="${label} 레벨"></progress>`;b.type='button';b.dataset.upgrade=key;b.textContent=u[key]===5?'MAX':`🪙 ${money(UPGRADE_COSTS[u[key]])}`;b.disabled=u[key]===5||p.coins<UPGRADE_COSTS[u[key]];b.onclick=()=>safe(()=>{garage.upgrade(key);api.effect('special');renderGarage();});card.append(b);$('race-upgrades').append(card);}
  for(const b of $('race-categories').children)b.setAttribute('aria-pressed',String(b.dataset.category===p.selectedCategory));$('race-car-grid').replaceChildren();
  for(const car of CARS.filter(c=>p.selectedCategory==='all'||p.selectedCategory===c.category)){const owned=p.unlockedCars.includes(car.id),selected=p.selectedCarId===car.id,card=document.createElement('article'),preview=document.createElement('canvas'),b=document.createElement('button');card.className=selected?'selected':'';card.dataset.car=car.id;preview.width=84;preview.height=132;preview.setAttribute('aria-hidden','true');const pc=preview.getContext('2d');pc.scale(2,2);drawRaceCar(pc,21,33,21,42,0,car);const words=document.createElement('div');words.innerHTML=`<small>${car.category==='supercar'?'🔥 ':''}${car.tag}</small><h3>${car.name}</h3><span>${garage.data.upgrades[car.id].speed>1?'튜닝 ':''}${car.maxSpeed+(garage.data.upgrades[car.id].speed-1)*11} km/h</span><small>핸들링 ${Math.round(car.handling*650)} · 니트로 ${Math.round(car.nitroPower*50)}</small>`;b.type='button';b.dataset.carAction=car.id;b.textContent=selected?'선택 완료 ✓':owned?'차량 선택':`🪙 ${money(car.price)}`;b.disabled=selected||!owned&&p.coins<car.price;b.onclick=()=>safe(()=>{garage.chooseCar(car.id);api.effect('special');renderGarage();});card.append(preview,words,b);$('race-car-grid').append(card);}
  $('race-difficulties').replaceChildren();for(const diff of Object.values(DIFFICULTIES)){const b=document.createElement('button');b.type='button';b.dataset.difficulty=diff.id;b.setAttribute('aria-pressed',String(diff.id===p.selectedDifficulty));b.innerHTML=`<strong>${diff.label}</strong><small>${(diff.length/1000).toFixed(1)} km · ${diff.id==='easy'?'완만한 커브':diff.id==='hard'?'급커브 · 추격전':'극한 커브 · 집중단속'}</small><span>1위 +${money(Math.round(diff.reward*(1+(p.stage-1)*.15)))} 🪙</span>`;b.onclick=()=>safe(()=>{garage.select('selectedDifficulty',diff.id);renderGarage();});$('race-difficulties').append(b);}
  $('race-start').textContent=p.activeRace?'🏁 진행 중 레이스 이어가기':`🏁 STAGE ${p.stage} · ${DIFFICULTIES[p.selectedDifficulty].label} 출발!`;$('race-fresh').hidden=!p.activeRace;
 }
 $('race-categories').onclick=e=>{const b=e.target.closest('[data-category]');if(b)safe(()=>{garage.select('selectedCategory',b.dataset.category);renderGarage();});};
 function start(fresh=false){
  if(!garage)return;resetInputs();engine.unlock();const next=!fresh&&garage.data.activeRace?RaceSimulation.restore(garage.data.activeRace):null;
  const candidate=next||new RaceSimulation({car:garage.car,difficulty:garage.data.selectedDifficulty,stage:garage.data.stage});garage.checkpoint(candidate);race=candidate;settled=null;hasResult=false;manualPause=false;last=0;autosave=0;$('race-garage').hidden=true;$('race-play').hidden=false;$('race-result').hidden=true;$('race-paused').hidden=true;
  $('race-track').querySelectorAll('.race-rival-marker').forEach(e=>e.remove());for(let i=0;i<6;i++){const marker=document.createElement('span');marker.className='race-rival-marker';marker.id='race-rival-'+i;marker.textContent=['😈','👾','👹','🤖','👽','💀'][i];$('race-track').append(marker);}canvas.focus({preventScroll:true});updateHud();api.active(true);
 }
 function toGarage(){save();resetInputs();race=null;manualPause=false;$('race-play').hidden=true;$('race-garage').hidden=false;renderGarage();api.active(false);}
 function pause(){resetInputs();if(race&&['countdown','racing'].includes(race.phase)){manualPause=true;$('race-paused').hidden=false;}safe(save);}
 function settle(){if(settled)return settled;settled=garage.finish(race.result);return settled;}
 function showResult(){
  const r=race.result;resetInputs();hasResult=true;try{settle();$('race-result-status').textContent='보상과 다음 스테이지를 저장했어요.';}catch(error){$('race-result-status').textContent='보상 저장을 다시 시도해 주세요. '+error.message;}
  const bonus=Math.round(race.diff.reward*(1+(r.stage-1)*.15)*[0,1,.7,.5,.35,.25,.2,.15][r.rank]);
  $('race-result-icon').textContent=['','🏆','🥈','🥉','🔥','⚡','💨','🏁'][r.rank];$('race-result-title').textContent=`${r.rank}위 · ${r.rank===1?'압도적 챔피언!':'레이스 완주!'}`;$('race-result-stage').textContent=`${race.diff.label} · STAGE ${r.stage} → ${r.stage+1}`;$('race-result-details').replaceChildren();
  for(const [label,value]of [['주행 시간',r.seconds.toFixed(1)+'초'],['도로 코인 · 이벤트','+'+money(r.trackCoins)+' 🪙'],['순위 완주 보상','+'+money(bonus)+' 🪙'],['총 획득 동전','+'+money(r.trackCoins+bonus)+' 🪙']]){const row=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;row.append(dt,dd);$('race-result-details').append(row);}
  $('race-countdown').hidden=true;$('race-result').hidden=false;api.effect('special');updateWallet();
 }
 $('race-start').onclick=()=>safe(()=>start());$('race-fresh').onclick=()=>safe(()=>{if(confirm('진행 중 레이스 대신 새로 출발할까요? 차량과 동전은 유지돼요.'))start(true);});$('race-home').onclick=()=>safe(toGarage);$('race-pause').onclick=pause;$('race-resume').onclick=()=>{resetInputs();engine.unlock();manualPause=false;last=0;$('race-paused').hidden=true;};
 $('race-result-garage').onclick=()=>safe(()=>{settle();toGarage();});$('race-result-next').onclick=()=>safe(()=>{settle();start(true);});$('race-sound').onclick=()=>{api.toggleSound?.();engine.unlock();updateWallet();};
 for(const button of root.querySelectorAll('[data-drive]')){button.onpointerdown=e=>{if(e.button>0||blocked()||manualPause||race?.phase!=='racing')return;e.preventDefault();engine.unlock();touches.set(e.pointerId,button.dataset.drive);button.setPointerCapture?.(e.pointerId);button.classList.add('pressed');};const release=e=>{touches.delete(e.pointerId);if(![...touches.values()].includes(button.dataset.drive))button.classList.remove('pressed');};for(const event of ['pointerup','pointercancel','lostpointercapture'])button.addEventListener(event,release);}
 const keys={ArrowUp:'accel',KeyW:'accel',ArrowDown:'brake',KeyS:'brake',ArrowLeft:'left',KeyA:'left',ArrowRight:'right',KeyD:'right',Space:'nitro'};
 const physicalKeys=new Set();document.addEventListener('keydown',e=>{if(blocked()||manualPause||!race||race.phase!=='racing'||/INPUT|TEXTAREA|SELECT/.test(e.target?.tagName))return;if(keys[e.code]){e.preventDefault();physicalKeys.add(e.code);heldKeys.add(keys[e.code]);engine.unlock();}if(e.code==='Escape')pause();});document.addEventListener('keyup',e=>{physicalKeys.delete(e.code);const key=keys[e.code];if(key&&![...physicalKeys].some(code=>keys[code]===key))heldKeys.delete(key);});
 globalThis.addEventListener('blur',()=>{physicalKeys.clear();if(active())pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden){physicalKeys.clear();if(active())pause();}});globalThis.addEventListener('pagehide',()=>{engine.mute();safe(save);});
 function updateHud(){
  $('race-speed').textContent=Math.round(race.speed/race.car.scrollSpeed*race.car.maxSpeed);$('race-hud-stage').textContent='STAGE '+race.stage;$('race-hud-diff').textContent=race.diff.label;$('race-collected').textContent='🪙 +'+money(race.trackCoins);$('race-position').textContent=`${race.rank}위 / 7대 ${race.rank===1?'🏆':''}`;
  const pct=Math.min(100,race.distance/race.length*100);$('race-progress-fill').style.width=pct+'%';$('race-player-marker').style.left=pct+'%';race.rivals.forEach((r,i)=>{const m=$('race-rival-'+i);if(m)m.style.left=Math.min(100,r.distance/race.length*100)+'%';});$('race-nitro').value=race.nitro;$('race-nitro-value').textContent=Math.round(race.nitro)+'%';
  $('race-countdown').hidden=race.phase!=='countdown';$('race-countdown').textContent=Math.max(1,Math.ceil(race.countdown/.75));const sharp=(race.curve(race.distance+220)-race.curve(race.distance+160))/60;$('race-event').hidden=!race.policeLeft&&!(Math.abs(sharp)>.24&&race.speed>7);$('race-event').textContent=race.policeLeft?`🚨 경찰 추격전 · ${Math.ceil(race.policeLeft/60)}초 남음`:`${sharp>0?'↪':'↩'} 급커브! 브레이크로 감속하세요`;
 }
 function frame(now){const dt=last?Math.min(.1,(now-last)/1000):0;last=now;
  if(active()&&race){const paused=blocked()||manualPause;const input=drive();if(!paused){race.update(dt,input);for(const event of race.events.splice(0)){if(event.type==='coin')api.effect('merge');if(['jump','escaped','go'].includes(event.type))api.effect('special');if(event.type==='hit')api.effect('over');if(event.type==='police')api.toast('🚨 경찰 추격전! 점프대나 니트로로 따돌리세요.');}if(race.phase==='finished'&&!hasResult)showResult();autosave+=dt;if(autosave>5&&race.phase!=='finished'){autosave=0;safe(save);}}
   else resetInputs();drawRaceScene(ctx,race,now/1000,input);updateHud();engine.update(!paused&&race.phase==='racing'&&race.speed>.5,race.speed/19,api.settings?.());
  }else engine.mute();requestAnimationFrame(frame);
 }
 requestAnimationFrame(frame);
 const select=()=>{garage||=new RacingGarage();garage.save();if(!race){$('race-garage').hidden=false;$('race-play').hidden=true;renderGarage();}else pause();};
 function openLocker(){if(!garage)select();if(race)toGarage();$('race-garage').hidden=false;$('race-car-grid').scrollIntoView?.({behavior:'smooth',block:'center'});}
 const records=document.createElement('dialog');records.id='race-records-dialog';records.className='wide-dialog';records.innerHTML='<button type="button" class="dialog-close" aria-label="레이싱 기록 닫기">×</button><p class="eyebrow">SPEED GARDEN RECORDS</p><h2>나의 레이싱 기록</h2><dl></dl><p class="race-records-note"></p>';document.body.append(records);records.querySelector('button').onclick=()=>records.close();records.addEventListener('close',api.resume);
 function openRecords(){if(!garage)select();const p=garage.data,list=records.querySelector('dl');list.replaceChildren();for(const [name,value]of [['현재 스테이지',p.stage],['완주한 레이스',p.completedRaces+'회'],['우승',p.wins+'회'],['최고 순위',p.completedRaces?p.bestRank+'위':'아직 없음'],['누적 획득 동전',money(p.earnedCoins)],['주행 시간',money(p.seconds)+'초'],['보유 차량',p.unlockedCars.length+' / 18']]){const row=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=name;dd.textContent=value;row.append(dt,dd);list.append(row);}records.querySelector('.race-records-note').textContent=`5회 완주마다 공용 보석 5개 · 다음 보상까지 ${5-p.completedRaces%5}회`;api.open(records.id);}

 return {select,save,leave:pause,openLocker,openRecords,focusMode:()=>{openLocker();$('race-difficulties').scrollIntoView?.({behavior:'smooth',block:'center'});},restart:()=>safe(()=>{if(confirm('차량과 동전을 유지하고 레이스를 다시 시작할까요?'))start(true);}),mode:()=> 'classic',model:()=>garage,simulation:()=>race};
}
